INSERT INTO "page_workflow_steps" ("_order", "_parent_id", "id", "step_number", "title", "description") VALUES (1, 6, '6abd2ea0b9b8e374bc8da525', 1, 'Discover & Scope', 'We map the product against hardware, firmware, mechanical, and software requirements at the scoping call.');
INSERT INTO "page_workflow_steps" ("_order", "_parent_id", "id", "step_number", "title", "description") VALUES (2, 6, '6abd2ea0b9b8e374bc8da526', 2, 'Design & Build', 'PCB layout, firmware, enclosure, and UI/UX move in parallel under one roof.');
INSERT INTO "page_workflow_steps" ("_order", "_parent_id", "id", "step_number", "title", "description") VALUES (3, 6, '6abd2ea0b9b8e374bc8da527', 3, 'Validate & Deploy', 'Bring-up, HIL testing, and certification prep before the first unit ships.');
INSERT INTO "page" ("id", "title", "heading", "subheading", "url", "body", "cta_label", "cta_href", "company_facts_name", "company_facts_location", "company_facts_contact_email", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "eyebrow", "page_type", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "hero_image_id") VALUES (1, 'Home', 'Electronics Product Development from India — One Team, Schematic to Cloud.', '', '/', '{"root":{"type":"root","children":[{"type":"paragraph","children":[],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', '', NULL, NULL, NULL, 'Canopy Embedded Labs | Electronics Product Development, India', 'Full-stack electronics product development: PCB design, firmware, enclosures, UI/UX and IoT cloud apps from one team. No vendor handoffs.', '', 1, 1, 'Organization', '2026-10-10T10:44:20.697Z', '2026-09-30T15:45:31.461Z', 'published', '', 'landing', '', '', '', NULL, NULL);
INSERT INTO "page" ("id", "title", "heading", "subheading", "url", "body", "cta_label", "cta_href", "company_facts_name", "company_facts_location", "company_facts_contact_email", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "eyebrow", "page_type", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "hero_image_id") VALUES (3, 'Portfolio', 'Ideas We''ve Turned Into Working Products.', 'Every product here started as somebody else''s idea and a gap in execution capability — no in-house hardware, firmware, or mechanical team to close it. We closed it. Pick a product from the index below to see the full build story, in place — no page reload.', '/work/', NULL, '', '', NULL, NULL, NULL, 'BMS, Charger & IoT Projects | Canopy Embedded Labs', 'Electronics product development portfolio: a smart BMS, a dual-channel Li-ion charger and a BLE Mesh + RS485 energy meter node.', '', 1, 1, 'auto', '2026-10-10T10:44:21.803Z', '2026-09-30T15:45:36.210Z', 'published', 'Electronics Product Development Portfolio', 'landing left', '', '', '', NULL, NULL);
INSERT INTO "page" ("id", "title", "heading", "subheading", "url", "body", "cta_label", "cta_href", "company_facts_name", "company_facts_location", "company_facts_contact_email", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "eyebrow", "page_type", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "hero_image_id") VALUES (5, 'Insights', 'Engineering Notes From Inside the Build.', 'The same technical breakdowns we post to LinkedIn — recalls, memory architecture, signal integrity, OTA pipelines — published here in full, so they''re searchable and citable long after the post scrolls out of a feed.', '/insights/', NULL, 'Browse Articles', '#latest-articles', NULL, NULL, NULL, 'Embedded Engineering Insights | Canopy Embedded Labs', 'Engineering insights on firmware, PCB design, BMS, OTA and IoT, written for founders and CTOs making hardware product decisions.', '', 1, 1, 'auto', '2026-10-10T10:44:21.460Z', '2026-09-30T15:45:36.520Z', 'published', 'Embedded Engineering Insights', 'landing', '', '', '', NULL, NULL);
INSERT INTO "page" ("id", "title", "heading", "subheading", "url", "body", "cta_label", "cta_href", "company_facts_name", "company_facts_location", "company_facts_contact_email", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "eyebrow", "page_type", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "hero_image_id") VALUES (6, 'Engagement Model', 'See the process. Talk to an engineer to start.', 'Whether you''re starting from an idea or already mid-build, the Productized R&D Subscription puts hardware, firmware, mechanical, and cloud under one roof. Six steps, start to kickoff. Send the form and an engineer follows up — no need to wait for a call slot to open up.', '/engagement-model/', '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"We don''t hand off a spec sheet and disappear. One team stays hands-on from first schematic to field-ready product — no vendor handoffs in between.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', '', NULL, NULL, NULL, 'Productized R&D Subscription | Canopy Embedded Labs', 'One contract for hardware, firmware, mechanical and cloud. Six steps from scoping call to kickoff, with fixed-milestone pricing.', '', 1, 1, 'FAQPage', '2026-10-10T10:44:17.994Z', '2026-09-30T15:45:36.732Z', 'published', 'Productized R&D Subscription', 'landing', '', '', '', NULL, NULL);
