INSERT INTO "section" ("id", "title", "section_key", "heading", "heading_first_line", "heading_second_line", "subheading", "summary", "eyebrow", "tag_line", "highlight", "type", "image_id", "image_url", "logo", "image_alt", "background_image", "background_video", "preview_alt", "mockup_assistant_name", "mockup_scheduling_message", "mockup_sync_title", "mockup_telemetry_title", "body", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "controls_tabs_label", "controls_previous_label", "controls_next_label", "updated_at", "created_at", "variant", "columns", "anchor", "tags", "hidden", "logo_media_id", "background_image_media_id", "background_video_media_id") VALUES (43, 'about · why', 'why', 'Why We Exist', '', '', '', '', '01', '', '', 'text', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Most hardware products are built by five vendors: one for the PCB, one for firmware, one for the enclosure, one for industrial design, one for the app. Nobody owns the gaps between them, so the founder or CTO ends up managing vendors instead of the product. Canopy Embedded Labs was set up to remove those gaps — every discipline in one team, under one contract.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', '', '', '', NULL, NULL, NULL, '2026-10-11T05:33:45.796Z', '2026-10-09T13:01:03.021Z', 'lead', '', '', '', 0, NULL, NULL, NULL);
INSERT INTO "section" ("id", "title", "section_key", "heading", "heading_first_line", "heading_second_line", "subheading", "summary", "eyebrow", "tag_line", "highlight", "type", "image_id", "image_url", "logo", "image_alt", "background_image", "background_video", "preview_alt", "mockup_assistant_name", "mockup_scheduling_message", "mockup_sync_title", "mockup_telemetry_title", "body", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "controls_tabs_label", "controls_previous_label", "controls_next_label", "updated_at", "created_at", "variant", "columns", "anchor", "tags", "hidden", "logo_media_id", "background_image_media_id", "background_video_media_id") VALUES (44, 'about · who', 'who', 'Who We Are', '', '', 'Led by a Principal Solution Architect with 13+ years of R&D experience, the team brings 25+ years of R&D experience across BMS/EV, industrial IoT, healthcare devices, automotive and energy metering.', '', '02', '', '', 'team', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', '', '', NULL, NULL, NULL, '2026-10-10T10:44:15.213Z', '2026-10-09T13:01:03.156Z', '', '', '', '', 0, NULL, NULL, NULL);
INSERT INTO "section" ("id", "title", "section_key", "heading", "heading_first_line", "heading_second_line", "subheading", "summary", "eyebrow", "tag_line", "highlight", "type", "image_id", "image_url", "logo", "image_alt", "background_image", "background_video", "preview_alt", "mockup_assistant_name", "mockup_scheduling_message", "mockup_sync_title", "mockup_telemetry_title", "body", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "controls_tabs_label", "controls_previous_label", "controls_next_label", "updated_at", "created_at", "variant", "columns", "anchor", "tags", "hidden", "logo_media_id", "background_image_media_id", "background_video_media_id") VALUES (45, 'about · build', 'build', 'What We Build', '', '', '', '', '03', '', '', 'text', NULL, NULL, NULL, '', NULL, NULL, NULL, NULL, NULL, NULL, NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Multi-layer PCBs and BMS circuitry, RTOS and embedded Linux firmware with an OTA-ready architecture, IP67-rated enclosures, touchscreen HMIs, and the mobile apps and cloud dashboards that connect them. See our ","version":1},{"type":"link","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"capabilities","version":1}],"direction":null,"format":"","indent":0,"version":3,"fields":{"linkType":"custom","newTab":false,"url":"/#disciplines"}},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" and our ","version":1},{"type":"link","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"projects","version":1}],"direction":null,"format":"","indent":0,"version":3,"fields":{"linkType":"custom","newTab":false,"url":"/work/"}},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":".","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'Explore our capabilities', '/#disciplines', '', '', NULL, NULL, NULL, '2026-10-10T10:44:15.365Z', '2026-10-09T13:01:03.225Z', 'surface', '', '', 'Hardware, Firmware, Embedded Software, Mechanical Engineering, UI/UX & HMI, Mobile Applications, Cloud / IoT, Product Engineering', 0, NULL, NULL, NULL);
