INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (205, 'The Scoping Call', '', 'Connect with us over a call.', '01', '', '', '', '', NULL, NULL, '', '', '', 'A working call, not a sales pitch — we get straight to what you''re building, where it stands today, and which disciplines actually need to be in the room.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:16.258Z', '2026-10-09T13:01:09.342Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (206, 'Select Your Scope', '', 'Pick exactly what you need us for.', '02', '', '', '', '', NULL, NULL, '', '', '', 'Take the full stack — hardware, firmware, mechanical & industrial design, UI/UX, apps/cloud — or slot us in around what you already have in-house.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:16.299Z', '2026-10-09T13:01:09.361Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (207, 'Submit the PRD', '', 'Bring us what you have — we scope against it, not a guess.', '03', '', '', '', '', NULL, NULL, '', '', '', 'Share your product requirements doc, even a rough one. It''s what the proposal gets priced and milestoned against.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:16.341Z', '2026-10-09T13:01:09.380Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (208, 'Get a Proposal', '', 'Fixed milestones, priced against your actual spec.', '04', '', '', '', '', NULL, NULL, '', '', '', 'A scoped proposal comes back — real deliverables and a real number, not an open-ended hourly estimate.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:16.386Z', '2026-10-09T13:01:09.407Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (209, 'Accept & Send PO', '', 'One contract. One signature.', '05', '', '', '', '', NULL, NULL, '', '', '', 'Accept the proposal and issue a PO — no separate contracts per discipline, no vendor-by-vendor negotiation.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:16.430Z', '2026-10-09T13:01:09.425Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (210, 'Kickoff', '', 'Ideate. Innovate. Deploy.', '06', '', '', '', '', NULL, NULL, '', '', 'highlight', 'The same team that scoped it is the team that builds it — work starts against the milestones in the proposal.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:16.473Z', '2026-10-09T13:01:09.445Z', '');
