INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (231, 'Hardware & PCB', 'Get the physical layer right once — before a respin costs you the schedule.', '', '01', '', '', '', '', 13, NULL, 'Hardware and PCB discipline clip', '', '', 'Multi-layer layouts, SI/PI, and BMS circuitry, designed by the same team that writes the firmware running on them.', NULL, NULL, '', 'Learn more', '/capabilities/pcb-design/', '', '', '', '2026-10-12T06:02:38.496Z', '2026-10-09T13:01:10.404Z', 'Multi-Layer PCB, Analog Design, RF Design, Power Electronics, HF Design, FPGA Design, SoC Design');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (232, 'Firmware Engineering', 'RTOS and OTA built by the team that wrote the board''s schematic.', '', '02', '', '', '', '', 6, NULL, 'Firmware engineering discipline visual', '', '', 'FreeRTOS, Zephyr, embedded Linux, and dual-bank signed OTA — no guessing what the hardware team shipped.', NULL, NULL, '', 'Learn more', '/capabilities/firmware/', '', '', '', '2026-10-12T05:13:32.407Z', '2026-10-09T13:01:10.423Z', 'IoT, Battery-Powered Devices, Embedded Linux, Sensor Fusion, BSP & Drivers, RTOS (FreeRTOS / Zephyr), OTA & Bootloaders');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (233, 'Mechanical & Industrial Design', 'DFM-checked before tooling, form and finish decided with production cost already in view.', '', '03', '', '', '', '', 14, NULL, 'Mechanical and enclosure discipline clip', '', '', 'Thermal CFD simulation, IP67/IP68 sealing, and CMF specification, validated against real tolerance stack-ups — not handed off between two separate teams.', NULL, NULL, '', 'Learn more', '/capabilities/mechanical-industrial-design/', '', '', '', '2026-10-12T06:02:38.723Z', '2026-10-09T13:01:10.441Z', 'DFM-Optimized CAD, Thermal CFD Simulation, IP67 / IP68 Sealing, Tolerance Stack-Up Analysis, Form Factor Optimization, CMF Specification, Human-Centered HMI');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (234, 'UI/UX & HMI', 'Every screen designed against the real firmware API, not a guess at one.', '', '04', '', '', '', '', 15, NULL, 'UI/UX and HMI discipline clip', '', '', 'Figma prototyping, embedded touchscreen HMI, and brand systems built alongside the hardware, not after it.', NULL, NULL, '', 'Learn more', '/capabilities/hmi-ui-ux/', '', '', '', '2026-10-12T06:02:38.940Z', '2026-10-09T13:01:10.459Z', 'Figma Prototyping, Embedded Touchscreen HMI, Corporate Brand Systems, Design Systems, Usability Testing, Responsive Web UI');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (235, 'Apps & Cloud', 'Provisioning and dashboards shipped from the same sprint as the board.', '', '05', '', '', '', '', 16, NULL, 'Apps and cloud discipline clip', '', '', 'iOS/Android BLE provisioning, cloud IoT dashboards, and full-stack web — one team''s release cycle, not five.', NULL, NULL, '', 'Learn more', '/capabilities/iot-apps-cloud/', '', '', '', '2026-10-12T06:02:39.149Z', '2026-10-09T13:01:10.477Z', 'iOS & Android, BLE / Wi-Fi Provisioning, Cloud IoT Dashboards, Full-Stack Web, REST / MQTT APIs, Desktop Calibration Tools');
