INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (239, 'Consumer Tech', '', '', '', '', '', '', '', NULL, NULL, '', '', '', 'Compact, battery-powered and connected devices, from first schematic to enclosure and companion app.', NULL, NULL, '', '', '/industries/consumer-tech/', '', '', '', '2026-10-10T10:44:19.249Z', '2026-10-09T13:01:10.608Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (240, 'Smart Homes', '', '', '', '', '', '', '', NULL, NULL, '', '', '', 'BLE and Wi-Fi connected devices with provisioning apps, cloud dashboards and OTA-ready firmware.', NULL, NULL, '', '', '/industries/smart-homes/', '', '', '', '2026-10-10T10:44:19.290Z', '2026-10-09T13:01:10.625Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (241, 'Building Management', '', '', '', '', '', '', '', NULL, NULL, '', '', '', 'BLE mesh sensor and relay networks, energy metering and cloud dashboards for buildings.', NULL, NULL, '', '', '/industries/building-management/', '', '', '', '2026-10-10T10:44:19.333Z', '2026-10-09T13:01:10.645Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (242, 'Discover & Scope', '', '', '01', '', '', '', '', NULL, NULL, '', '', '', 'We map the product against hardware, firmware, mechanical, and software requirements at the scoping call — and flag the failure points before a schematic or a line of code is committed.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:19.523Z', '2026-10-09T13:01:10.722Z', 'Contact details automatically, Your Client Interactions, Helps you scope software requirements at the scoping call');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (243, 'Design & Build', '', '', '02', '', '', '', '', NULL, NULL, '', '', '', 'PCB layout, firmware, enclosure, and UI/UX move in parallel under one roof — not sequentially across five vendors who''ve never spoken to each other.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:19.563Z', '2026-10-09T13:01:10.741Z', 'Parallel hardware & firmware tracks, One integration owner, Weekly build reviews');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (244, 'Validate & Deploy', '', '', '03', '', '', '', '', NULL, NULL, '', '', '', 'Bring-up, HIL testing, and certification prep before the first unit ships — with OTA infrastructure built in from day one, not bolted on after the first field failure.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:19.601Z', '2026-10-09T13:01:10.764Z', 'Pre-compliance EMC testing, Pilot-run validation, Production handover pack');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (245, 'First-Spin PCB Engineering', '', '', '01', '', '', '', '', NULL, NULL, '', '', '', 'SI/PI, EMC and DFM checks before layout freeze — so you pay for one board spin, not three.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:19.792Z', '2026-10-09T13:01:10.857Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (246, 'One Team, Schematic to Cloud', '', '', '02', '', '', '', '', NULL, NULL, '', '', '', 'Hardware, firmware, mechanical, UI/UX and cloud under one roof, one contract, zero vendor handoffs.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:19.834Z', '2026-10-09T13:01:10.874Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (247, 'Design-to-Manufacturing Continuity', '', '', '03', '', '', '', '', NULL, NULL, '', '', '', 'We stay through production — DFM, sourcing, assembly support and bring-up with your manufacturer.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:19.878Z', '2026-10-09T13:01:10.893Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (248, 'Field-Ready Reliability by Design', '', '', '04', '', '', '', '', NULL, NULL, '', '', '', 'OTA-ready firmware, IP67 sealing and thermal validation from day one — patches, not recalls.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:19.920Z', '2026-10-09T13:01:10.912Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (249, 'Proven Multi-Sector Depth', '', '', '05', '', '', '', '', NULL, NULL, '', '', '', '25+ years of R&D experience across BMS/EV, industrial IoT, medical devices and automotive electronics.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:19.962Z', '2026-10-09T13:01:10.932Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (250, 'Fast-Track Your MVP', '', '', '06', '', '', '', '', NULL, NULL, '', '', '', 'Parallel-path hardware, firmware and mechanical work can cut MVP delivery time by up to 50%, compared to running each discipline through a separate vendor.', NULL, NULL, '', '', '', '', '', '', '2026-10-10T10:44:20.004Z', '2026-10-09T13:01:10.951Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (251, 'Faster MVP Delivery', '', '', '', 'Up to 50%', '', '', '', NULL, NULL, '', '', '', '', NULL, NULL, '', '', '', '', '', 'stat', '2026-10-10T10:44:20.200Z', '2026-10-09T13:01:11.035Z', '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "index", "value", "category", "role", "date", "image_id", "image_url", "image_alt", "icon", "theme", "short_description", "description", "additional_description", "body", "cta_label", "cta_url", "read_more_label", "linkedin_url", "type", "updated_at", "created_at", "tags") VALUES (252, 'Not Five Vendors', '', '', '', '1 Team', '', '', '', NULL, NULL, '', '', '', '', NULL, NULL, '', '', '', '', '', 'stat', '2026-10-10T10:44:20.237Z', '2026-10-09T13:01:11.055Z', '');
