INSERT INTO "case_study_overview" ("_order", "_parent_id", "id", "label", "text") VALUES (1, 5, '6aca16f520848b23b44f71ab', 'The idea', 'A battery management system that can be updated in the field without a recall.');
INSERT INTO "case_study_overview" ("_order", "_parent_id", "id", "label", "text") VALUES (2, 5, '6aca16f520848b23b44f71ac', 'The gap', 'No in-house team spanning circuit design, RTOS firmware and validation.');
INSERT INTO "case_study_overview" ("_order", "_parent_id", "id", "label", "text") VALUES (3, 5, '6aca16f520848b23b44f71ad', 'Our role', 'We were that team.');
INSERT INTO "case_study_overview" ("_order", "_parent_id", "id", "label", "text") VALUES (1, 6, '6aca16f720848b23b44f71c0', 'The idea', 'A charging platform where the power stage and the control firmware are designed together, not bolted on after the fact.');
INSERT INTO "case_study_overview" ("_order", "_parent_id", "id", "label", "text") VALUES (2, 6, '6aca16f720848b23b44f71c1', 'The gap', 'Most contract shops hand power electronics and firmware to two different vendors. We''re one team for both.');
INSERT INTO "case_study_overview" ("_order", "_parent_id", "id", "label", "text") VALUES (3, 6, '6aca16f720848b23b44f71c2', 'Our role', 'We were that team.');
INSERT INTO "case_study_overview" ("_order", "_parent_id", "id", "label", "text") VALUES (1, 7, '6aca16f820848b23b44f71c7', 'The idea', 'Retrofit legacy energy meters with wireless connectivity without touching the meter''s own comms stack.');
INSERT INTO "case_study_overview" ("_order", "_parent_id", "id", "label", "text") VALUES (2, 7, '6aca16f820848b23b44f71c8', 'The gap', 'BLE Mesh and RS485/Modbus rarely live on the same board, let alone the same firmware team. We built both sides.');
INSERT INTO "case_study_overview" ("_order", "_parent_id", "id", "label", "text") VALUES (3, 7, '6aca16f820848b23b44f71c9', 'Our role', 'We were that team.');
