INSERT INTO "blog" ("id", "title", "slug", "heading", "category", "dek", "byline", "published_date", "updated_date", "body", "content_upgrade_label", "content_upgrade_checklist_link_id", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "tags", "image_id", "featured", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (12, 'ISO 13485 Doesn''t Start With a Document. It Starts With a Commit.', 'iso-13485-starts-with-a-commit', 'ISO 13485 Doesn''t Start With a Document. It Starts With a Commit.', 'Medical Devices', 'Quality events cost the medical device industry $7–8.5B a year (source). Most trace back to design controls that existed on paper only.', 'By the Canopy Embedded Labs engineering team', '2026-09-26T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Quality events cost the medical device industry $7–8.5B a year (source). Most trace back to design controls that existed on paper only.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', NULL, 'ISO 13485 Doesn''t Start With a Document. It Starts With a Commit. | Canopy Embedded Labs', 'Quality events cost the medical device industry $7–8.5B a year (source). Most trace back to design controls that existed on paper only.', '', 1, 1, 'auto', '2026-10-10T10:44:10.827Z', '2026-10-09T13:01:02.173Z', 'published', 'Medical Devices, ISO 13485, Design Controls', NULL, 0, '', '', '', NULL);
INSERT INTO "blog" ("id", "title", "slug", "heading", "category", "dek", "byline", "published_date", "updated_date", "body", "content_upgrade_label", "content_upgrade_checklist_link_id", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "tags", "image_id", "featured", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (13, 'The Most Common IoT Support Ticket Isn''t a Hardware Bug', 'iot-support-ticket-ble-provisioning', 'The Most Common IoT Support Ticket Isn''t a Hardware Bug', 'IoT · Mobile', 'It''s BLE provisioning. What actually reduces provisioning-related returns, from firmware/app alignment to real-world RF testing.', 'By the Canopy Embedded Labs engineering team', '2026-09-25T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"It''s BLE provisioning. What actually reduces provisioning-related returns, from firmware/app alignment to real-world RF testing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'Get the UI/UX & Cloud Readiness Checklist', 2, 'The Most Common IoT Support Ticket Isn''t a Hardware Bug | Canopy Embedded Labs', 'It''s BLE provisioning. What actually reduces provisioning-related returns, from firmware/app alignment to real-world RF testing.', '', 1, 1, 'auto', '2026-10-10T10:44:11.278Z', '2026-10-09T13:01:02.358Z', 'published', 'IoT & Mobile, BLE, Provisioning', NULL, 0, '', '', '', NULL);
