INSERT INTO "blog" ("id", "title", "slug", "heading", "category", "dek", "byline", "published_date", "updated_date", "body", "content_upgrade_label", "content_upgrade_checklist_link_id", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "tags", "image_id", "featured", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (15, 'Shipping the First OTA Update Is the Real Product Launch', 'first-ota-update-product-launch', 'Shipping the First OTA Update Is the Real Product Launch', 'Firmware · OTA', 'Four things we check before calling an OTA pipeline production-ready — and why getting it wrong after ship is a firmware team working nights.', 'By the Canopy Embedded Labs engineering team', '2026-09-23T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Four things we check before calling an OTA pipeline production-ready — and why getting it wrong after ship is a firmware team working nights.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', NULL, 'Shipping the First OTA Update Is the Real Product Launch | Canopy Embedded Labs', 'Four things we check before calling an OTA pipeline production-ready — and why getting it wrong after ship is a firmware team working nights.', '', 1, 1, 'auto', '2026-10-10T10:44:12.174Z', '2026-10-09T13:01:02.730Z', 'published', 'Firmware & OTA, OTA, Release Engineering', NULL, 0, '', '', '', NULL);
INSERT INTO "blog" ("id", "title", "slug", "heading", "category", "dek", "byline", "published_date", "updated_date", "body", "content_upgrade_label", "content_upgrade_checklist_link_id", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "tags", "image_id", "featured", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (16, 'One Team. One Contract. Every Discipline Your Hardware Product Needs.', 'one-team-one-contract', 'One Team. One Contract. Every Discipline Your Hardware Product Needs.', 'Engagement Model', 'How the Productized R&D Subscription puts five disciplines under one roof and one fixed-milestone structure.', 'By the Canopy Embedded Labs engineering team', '2026-09-22T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"How the Productized R&D Subscription puts five disciplines under one roof and one fixed-milestone structure.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', NULL, 'One Team. One Contract. Every Discipline Your Hardware Product Needs. | Canopy Embedded Labs', 'How the Productized R&D Subscription puts five disciplines under one roof and one fixed-milestone structure.', '', 1, 1, 'auto', '2026-10-10T10:44:12.618Z', '2026-10-09T13:01:02.917Z', 'published', 'Engagement Model, Productized R&D', NULL, 0, '', '', '', NULL);
INSERT INTO "blog" ("id", "title", "slug", "heading", "category", "dek", "byline", "published_date", "updated_date", "body", "content_upgrade_label", "content_upgrade_checklist_link_id", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "tags", "image_id", "featured", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id") VALUES (17, 'What Hardware-in-the-Loop Testing Actually Looks Like', 'hardware-in-the-loop-testing---copy', 'What Hardware-in-the-Loop Testing Actually Looks Like', 'BMS · Behind the Scenes', 'Before firmware ever touches a real pack, it runs against a HIL rig scripted to inject failures on demand. Here''s why.', 'By the Canopy Embedded Labs engineering team', '2026-09-24T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Before firmware ever touches a real pack, it runs against a HIL rig scripted to inject failures on demand. Here''s why.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', NULL, 'What Hardware-in-the-Loop Testing Actually Looks Like | Canopy Embedded Labs', 'Before firmware ever touches a real pack, it runs against a HIL rig scripted to inject failures on demand. Here''s why.', '', 1, 1, 'auto', '2026-10-10T10:44:11.726Z', '2026-10-10T12:26:44.430Z', 'draft', 'BMS / EV, HIL Testing, Validation', NULL, 0, '', '', '', NULL);
INSERT INTO "_blog_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_category", "version_dek", "version_byline", "version_published_date", "version_updated_date", "version_body", "version_content_upgrade_label", "version_content_upgrade_checklist_link_id", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_image_id", "version_tags", "version_featured", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id") VALUES (170, 8, 'The Race Condition That Recalled 21,000 EVs', 'bms-race-condition-recall', 'The Race Condition That Recalled 21,000 EVs', 'BMS / EV · Firmware', 'A major automaker''s shared EV platform recalled roughly 21,000 vehicles for a defect inside the battery control unit — a memory-arbitration race between two ICs. Illustrative industry example, not a Canopy Embedded Labs engagement. Here''s what it should change about how you scope BMS and firmware work.', 'By the Canopy Embedded Labs engineering team', '2026-09-30T00:00:00.000Z', '2026-10-02T00:00:00.000Z', '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"A major automaker''s shared EV platform recalled ","version":1},{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"roughly 21,000 vehicles","version":1},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" for a defect inside the battery control unit.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Root Cause","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"list","listType":"number","tag":"ol","start":1,"children":[{"type":"listitem","value":1,"children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Two ICs on the board could write to the same memory address at the same time.","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"listitem","value":2,"children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"One overwrites the other mid-write.","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"listitem","value":3,"children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The battery ECU faults.","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"listitem","value":4,"children":[{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"The vehicle loses drive power on the road.","version":1}],"direction":null,"format":"","indent":0,"version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"This Isn''t Just a \"Software Bug\"","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"This isn''t a software bug in the vague sense marketing teams use. It''s a ","version":1},{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"concurrency and memory-arbitration failure","version":1},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" — the kind unit tests miss, that passes hardware validation, and only shows up when two independent silicon paths race for the same register under real-world timing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"OTA and Field Remediation","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The manufacturer could fix this with a software update, flashed at the dealer through the OBD-II port. ","version":1},{"type":"text","detail":0,"format":1,"mode":"normal","style":"","text":"Most hardware startups can''t.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"If your BMS or IoT node doesn''t have provisioned OTA and a ","version":1},{"type":"text","detail":0,"format":16,"mode":"normal","style":"","text":"ual-bank bootloade","version":1},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" from day one, the same class of bug means a truck roll or a physical recall — not a push notification.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Three Things This Should Change About How You Scope BMS/Firmware Work","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"01 · Shared memory access","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Shared memory access between any two ICs (companion chip, fuel gauge, processor) needs explicit arbitration — mutex, semaphore, or a single owner — documented in the architecture review, not discovered in the field.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"02 · OTA & rollback","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"OTA and rollback capability isn''t a \"phase 2\" feature. It''s what turns a per-vehicle recall into a near-zero-cost remote patch.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"03 · End-to-end ownership","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"When your chip vendor, RTOS integrator, and mechanical/enclosure team are three different vendors, concurrency bugs like this hide in the handoffs — nobody owns the full data path end to end.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Our Approach","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"We build BMS and embedded systems as one team — hardware, firmware, and infrastructure under one roof (see our ","version":1},{"type":"link","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"embedded firmware development","version":1}],"direction":null,"format":"","indent":0,"version":3,"fields":{"linkType":"custom","newTab":false,"url":"/capabilities/firmware/"}},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":" work and the ","version":1},{"type":"link","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Smart BMS project","version":1}],"direction":null,"format":"","indent":0,"version":3,"fields":{"linkType":"custom","newTab":false,"url":"/work/smart-bms/"}},{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":") — specifically so races like this get caught in architecture review, not in a regulatory filing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Scope a BMS or IoT product?","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"If you''re scoping a BMS or IoT product and want a second set of eyes on your memory/concurrency architecture before it ships, book a scoping call.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'Get the Checklist This Article Is Built On', 1, 'BMS Race Condition Recall: 3 Firmware Lessons | Canopy', 'A memory-arbitration race between two ICs forced a 21,000-vehicle EV recall. Three changes it should make to how you scope BMS firmware.', '', 1, 1, 'auto', '2026-10-10T10:35:51.216Z', '2026-10-09T13:01:01.415Z', 'published', '2026-10-10T10:35:51.258Z', '2026-10-10T10:35:51.258Z', 0, NULL, NULL, 'BMS / EV, Embedded Systems, BMS, EV Engineering, Firmware Engineering, Hardware Startups, Product Engineering', 1, '', '', '', NULL);
INSERT INTO "_blog_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_category", "version_dek", "version_byline", "version_published_date", "version_updated_date", "version_body", "version_content_upgrade_label", "version_content_upgrade_checklist_link_id", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_image_id", "version_tags", "version_featured", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id") VALUES (171, 9, 'Your Bootloader Isn''t a Feature. It''s Your Recall Insurance.', 'bootloader-recall-insurance', 'Your Bootloader Isn''t a Feature. It''s Your Recall Insurance.', 'Firmware · OTA', 'A recall is paid per unit; an OTA patch costs almost nothing.', 'By the Canopy Embedded Labs engineering team', '2026-09-29T00:00:00.000Z', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"A recall is paid per unit; an OTA patch costs almost nothing.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '', NULL, 'Your Bootloader Isn''t a Feature. It''s Your Recall Insurance. | Canopy Embedded Labs', 'A recall is paid per unit; an OTA patch costs almost nothing.', '', 1, 1, 'auto', '2026-10-10T10:35:51.652Z', '2026-10-09T13:01:01.628Z', 'published', '2026-10-10T10:35:51.692Z', '2026-10-10T10:35:51.692Z', 0, NULL, NULL, 'Firmware & OTA, OTA, Bootloader', 0, '', '', '', NULL);
