INSERT INTO "capability" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "included_heading", "why_heading", "why_text", "workflow_eyebrow", "workflow_heading", "workflow_intro", "workflow", "projects_heading", "insights_heading", "faq_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at") VALUES (1, 'Firmware Engineering', 'firmware', 'Embedded Firmware Development', 'Deep Firmware Engineering', 'Firmware built for field reliability — a bug becomes a remote patch, not a truck roll.', 'Talk to an Engineer', '#consultation', 'See it in a real product', '/work/smart-bms/', NULL, '', 'What''s included', '', '', 'The firmware workflow we work in, industry-standard flow', 'Seven stage-gates, industry-standard, no shortcuts to a demo.', 'The same sequence run on every firmware program — architecture decided before code, hardware-in-the-loop testing before real cells or motors are at risk, and a release gate before anything is called production-ready.', 'Architecture & Flow Diagrams | 
BSP & Driver Bring-Up | 
RTOS & Middleware Integration | 
Application Logic Development | 
Hardware-in-the-Loop Testing | 
Integration & Stress Testing | 
Field Validation & Release | ', 'Related Projects', 'Insights', 'FAQ', 'Embedded Firmware Development, India | Canopy Embedded Labs', 'FreeRTOS, Zephyr and embedded Linux firmware with dual-bank bootloaders and secure OTA, so a field bug becomes a remote patch.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-12T06:02:40.823Z', '2026-10-10T10:35:54.642Z');
INSERT INTO "capability" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "included_heading", "why_heading", "why_text", "workflow_eyebrow", "workflow_heading", "workflow_intro", "workflow", "projects_heading", "insights_heading", "faq_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at") VALUES (2, 'UI/UX & HMI', 'hmi-ui-ux', 'Embedded HMI Design', 'UI/UX Architecture & Embedded HMI', 'Embedded touchscreen HMI and business software UI, designed by people who understand the hardware constraints underneath it.', 'Talk to an Engineer', '#consultation', 'See it in a real product', '/work/smart-bms/', NULL, '', 'What''s included', 'Why It Matters', 'A UI designed without knowing the MCU''s refresh rate or RAM budget gets redesigned the week firmware bring-up starts. Because our UI designers sit with the firmware team, every screen is checked against the real display and the real API before it''s built.', '', '', '', '', 'Related Projects', 'Insights', 'FAQ', 'Embedded HMI & UI/UX Design | Canopy Embedded Labs', 'Embedded touchscreen HMI and product UI designed against the real display, MCU and firmware API — with Figma prototypes and brand systems.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-10T10:44:13.032Z', '2026-10-10T10:35:54.780Z');
INSERT INTO "capability" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "included_heading", "why_heading", "why_text", "workflow_eyebrow", "workflow_heading", "workflow_intro", "workflow", "projects_heading", "insights_heading", "faq_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at") VALUES (3, 'Apps & Cloud', 'iot-apps-cloud', 'IoT App & Cloud Dashboard Development', 'App Development & Cloud Systems', 'Mobile apps and cloud dashboards built against the same firmware spec from day one — not integrated at the end.', 'Talk to an Engineer', '#consultation', 'See it in a real product', '/work/ble-mesh-rs485-energy-meter/', NULL, '', 'What''s included', 'Why It Matters', 'BLE provisioning is one of the most common early-life support problems in IoT products, usually because the app and firmware were integrated at the end. Our app and firmware teams test against the same GATT spec from the first sprint.', '', '', '', '', 'Related Projects', 'Insights', 'FAQ', 'IoT App & Cloud Dashboard Development | Canopy Embedded Labs', 'iOS/Android BLE provisioning apps, cloud IoT dashboards and calibration software built against the same firmware spec from day one.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-10T12:28:46.927Z', '2026-10-10T10:35:54.897Z');
INSERT INTO "capability" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "included_heading", "why_heading", "why_text", "workflow_eyebrow", "workflow_heading", "workflow_intro", "workflow", "projects_heading", "insights_heading", "faq_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at") VALUES (4, 'Mechanical & Industrial Design', 'mechanical-industrial-design', 'IP67 Enclosure & Industrial Design', 'Mechanical & Industrial Design', 'Form, function, and manufacturability decided together — from concept sketch to first-article inspection, not handed off between two separate teams.', 'Talk to an Engineer', '#consultation', 'See it in a real product', '/work/dual-channel-charger/', NULL, '', 'Our Capabilities', '', '', 'The mechanical & industrial design workflow we work in, industry-standard flow', 'Nine stage-gates, industry-standard, no shortcuts to tooling.', 'One sequence from user research to production-ready hardware — form explored and rendered before it''s modeled in engineering CAD, DFM checked before a review closes, thermal and tolerance stack-up validated before a mold is cut, and first-article inspection before a design is called production-ready.', 'Research & User Insight | 
Concept Generation & Ideation | 
3D Rendering & Visualization | 
3D CAD Modeling & Engineering | 
DFM Review | 
Thermal & CFD Simulation | 
Tolerance Stack-Up Validation | 
Prototype (3D Print / CNC) | 
First Article Inspection & Tooling | ', 'Related Projects', 'Insights', 'FAQ', 'IP67 Enclosure & Industrial Design | Canopy Embedded Labs', 'DFM-ready enclosure CAD, thermal CFD, IP67/IP68 sealing, tolerance stack-up and CMF — form and manufacturability decided before tooling.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-10T10:44:13.478Z', '2026-10-10T10:35:55.029Z');
INSERT INTO "capability" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "included_heading", "why_heading", "why_text", "workflow_eyebrow", "workflow_heading", "workflow_intro", "workflow", "projects_heading", "insights_heading", "faq_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at") VALUES (5, 'PCB Design', 'pcb-design', 'PCB Design & Layout Services', 'Hardware Design & PCB Architecture', 'PCBs engineered for signal integrity and manufacturability from the first placement pass — designed to get the board right in the first spin, not patched before a certification deadline.', 'Talk to an Engineer', '#consultation', 'See it in a real product', '/work/smart-bms/', NULL, '', 'Our Capabilities', '', '', 'The design workflow we work in', 'Five Gates. Every Board. No Exceptions.', 'The same sequence run on every PCB program, from a first prototype to a production respin — nothing moves to layout without a signed-off schematic, and nothing goes to fab without a signed-off layout.', 'High-Level Block Diagram | 
Schematic Entry | 
Footprint Creation & Verification | 
PCB Layout Design | 
Gerber & Documentation | ', 'Related Projects', 'Insights', 'FAQ', 'PCB Design & Layout Services, India | Canopy Embedded Labs', 'Multi-layer PCB design with SI/PI, RF, power electronics and DFM built in from the first placement pass, by the team that writes the firmware.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-12T06:02:40.361Z', '2026-10-10T10:35:55.147Z');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (1, 2, '6aca16fd20848b23b44f71db', 'Embedded Touchscreens (HMI)', '', 'UI designed against the actual display''s refresh rate, RAM budget, and touch controller — not a spec sheet assumption.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (2, 2, '6aca16fd20848b23b44f71dc', 'Solution-Driven UI/UX for Business Needs', '', 'Interfaces designed around the workflow they serve, not a generic component library.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (3, 2, '6aca16fd20848b23b44f71dd', 'Figma Interactive Prototyping', '', 'Clickable prototypes validated with real users before a line of UI firmware is written.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (4, 2, '6aca16fd20848b23b44f71de', 'Corporate Brand Identity Systems', '', 'Typography, color, and visual language applied consistently from the product''s screen to its packaging to its website.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (1, 4, '6aca16fd20848b23b44f71e7', 'Design for Manufacturing (DFM-Optimized CAD)', '', 'Draft angles, wall thickness, and rib design checked against the actual molding or machining process before quoting tooling.', 'Draft Angle Analysis, Wall Thickness Optimization, Rib & Boss Design, Snap-Fit Design, Undercut Elimination');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (2, 4, '6aca16fd20848b23b44f71e8', 'Thermal CFD Simulation & Heat Dissipation', '', 'Airflow and heat-sink modeling under worst-case ambient — including India''s 45–55°C field reality, not a 25°C lab spec.', 'Airflow Simulation, Heat Sink Design, Thermal Interface Material Selection, Hot-Spot Mapping, Worst-Case Ambient Modeling');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (3, 4, '6aca16fd20848b23b44f71e9', 'Environmental Ingress Protection (IP67/IP68)', '', 'Gasket and seam design validated against real ingress conditions, not just the gasket datasheet.', 'Gasket & Seal Design, Seam & Joint Sealing, Ingress Testing (IEC 60529), Cable Gland & Connector Sealing');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (4, 4, '6aca16fd20848b23b44f71ea', 'Tolerance Stack-Up Validation', '', 'PCB, enclosure, and mating-part tolerances checked together before the first tooling quote — not discovered at first-article inspection.', 'GD&T Analysis, Worst-Case Stack-Up Modeling, Statistical (RSS) Tolerance Analysis, Mating-Part Fit Validation');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (5, 4, '6aca16fd20848b23b44f71eb', 'Form Factor Optimization', '', 'Enclosure geometry sized to the PCB and battery it actually holds, not a generic off-the-shelf shell.', 'Volumetric Packaging Study, Enclosure Sizing to PCB/Battery, Component Density Planning');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (6, 4, '6aca16fd20848b23b44f71ec', 'Product Aesthetics & Ergonomics', '', 'Grip, weight distribution, and button placement designed for how the device is actually held or mounted.', 'Grip & Handling Study, Weight Distribution, Control Placement');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (7, 4, '6aca16fd20848b23b44f71ed', 'CMF Specifications', '', 'Color, material, and finish specified with the manufacturing process in mind, not chosen from a swatch after tooling is locked.', 'Color Specification, Material Selection, Surface Finish Callouts');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (8, 4, '6aca16fd20848b23b44f71ee', 'Human-Centered Hardware Interfaces', '', 'Physical controls — buttons, dials, indicator lights — designed around how the product is actually used in the field.', 'Physical Control Layout, Indicator & Feedback Design, Field-Use Interaction Design');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (1, 3, '6aca16fd20848b23b44f71e1', 'Cross-Platform Mobile Apps', '', 'iOS/Android apps for BLE/Wi-Fi provisioning, tested against the same GATT spec the firmware team ships against.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (2, 3, '6aca16fd20848b23b44f71e2', 'Cloud IoT Dashboards & Telematics', '', 'Fleet-level visibility built on the device''s real telemetry schema, not retrofitted after launch.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (3, 3, '6aca16fd20848b23b44f71e3', 'Desktop Calibration / Engineering Software', '', 'Bench and factory-floor tools for calibration, diagnostics, and end-of-line test.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (4, 3, '6aca16fd20848b23b44f71e4', 'Full-Stack Web Architecture', '', 'The business-facing web layer — account management, provisioning, reporting — built by the same team that owns the device it talks to.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (1, 5, '6aca16fd20848b23b44f71f3', 'Multi-Layer PCB Design', '', 'Layer counts scoped to the signal and thermal budget, not defaulted to whatever the last board used.', '1-Layer, 2-Layer, 4–6 Layer, 8–16 Layer');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (2, 5, '6aca16fd20848b23b44f71f4', 'Analog Design', '', 'Mixed-signal circuits where the analog front-end doesn''t get drowned out by digital switching noise.', 'Signal Conditioning, Precision Voltage References, Op-Amp & Comparator Circuits, ADC/DAC Interfacing, Active Filter Design, Mixed-Signal Layout');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (3, 5, '6aca16fd20848b23b44f71f5', 'RF Design', '', 'Matched, shielded RF paths designed to pass certification on the first attempt.', 'Antenna Matching & Tuning, Impedance Matching Networks, Sub-GHz & 2.4GHz Radio Design, RF Shielding & Isolation, EMI/EMC Mitigation');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (4, 5, '6aca16fd20848b23b44f71f6', 'Power Electronics', '', 'Power stages designed with thermal and derating margins built in, not assumed.', 'Switch-Mode Power Supplies (SMPS), DC-DC Converter Design, Battery Management Systems (BMS), Motor Drive Circuits, High-Current Power Stages, Thermal & Derating Analysis');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (5, 5, '6aca16fd20848b23b44f71f7', 'HF Design', '', 'Signal integrity reviewed at the schematic stage, not discovered at the compliance lab.', 'Signal Integrity (SI) Analysis, Power Integrity (PI) Analysis, Controlled Impedance Stack-Ups, Differential Pair Routing');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (6, 5, '6aca16fd20848b23b44f71f8', 'FPGA Design', '', 'Custom logic where an MCU''s timing or I/O count runs out.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (7, 5, '6aca16fd20848b23b44f71f9', 'SoC Design', '', 'Application-processor-class designs for boards that need to run embedded Linux, not just an RTOS.', '');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (1, 1, '6aca16fc20848b23b44f71ce', 'Baremetal Development', '', 'Direct-to-silicon firmware where an RTOS''s overhead isn''t worth paying for.', 'Board Bring-Up, Peripheral Drivers, Interrupt-Driven Design, Clock & Power Configuration');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (2, 1, '6aca16fc20848b23b44f71cf', 'Real-Time Operating Systems', '', 'FreeRTOS and Zephyr architectures with task priorities and memory budgets decided up front, not discovered under load.', 'FreeRTOS, Zephyr, Task Priority & Scheduling, Memory Budgeting');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (3, 1, '6aca16fc20848b23b44f71d0', 'Embedded Linux', '', 'Full BSP bring-up and application layer for gateway-class and HMI-class devices.', 'BSP Bring-Up, Linux Application Layer, Gateway-Class Devices, HMI-Class Devices');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (4, 1, '6aca16fc20848b23b44f71d1', 'Ultra-Low-Power Architecture', '', 'Sleep-mode and duty-cycle design for battery products measured in months, not hours.', 'Sleep-Mode Design, Duty-Cycle Scheduling, Current Profiling, Coin-Cell Designs');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (5, 1, '6aca16fc20848b23b44f71d2', 'Secure OTA Updates', '', 'Signed images verified before they''re written to the inactive A/B partition, with automatic rollback on a failed or interrupted update.', 'Signed Images, Custom Dual-Bank Bootloader, A/B Partitions, Automatic Rollback');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (6, 1, '6aca16fc20848b23b44f71d3', 'Security', '', 'Flash readback protection, secure boot, and locked debug ports designed in before certification, not patched in after a teardown finds the gap.', 'Secure Boot, Flash Readback Protection, Locked Debug Ports');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (7, 1, '6aca16fc20848b23b44f71d4', 'Sensor Fusion & Predictive Maintenance', '', 'Multi-sensor fusion (IMU, current, thermal) feeding onboard health models that flag a failure mode before it happens — not just logging raw telemetry for someone else to interpret.', 'Multi-Sensor Fusion, Onboard Health Models, Failure-Mode Flagging');
INSERT INTO "capability_included" ("_order", "_parent_id", "id", "title", "icon", "text", "tags") VALUES (8, 1, '6aca16fc20848b23b44f71d5', 'Device Management', '', 'BLE/Wi-Fi provisioning, factory provisioning, remote diagnostics and fleet-level configuration built into the firmware from day one, not bolted on after the first support ticket.', 'BLE/Wi-Fi Provisioning, Factory Provisioning, Remote Diagnostics, Fleet Configuration');
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (1, 2, '6aca16fd20848b23b44f71df', 'chips', 'Stack we build on', '', 'Figma Prototyping, Embedded Touchscreen HMI, Corporate Brand Systems, Typography Systems', '', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (1, 4, '6aca16fd20848b23b44f71ef', 'rows', 'Materials We Work With', 'Material families we spec against for enclosures, brackets, and mechanical parts — pulled out of the capability list above so procurement and CTOs can scan them at a glance.', 'Metals: Aluminum 6061, Aluminum 5052, Stainless Steel 304
Plastics & Polymers: ABS, Polycarbonate, PC/ABS Blend, Nylon (PA)
Surface Finishes: Anodizing (Type II/III), Bead Blasting, Powder Coating, Silkscreen / Pad Printing', '', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (2, 4, '6aca16fd20848b23b44f71f0', 'rows', 'Stack we build on', '', 'CAD & Simulation: DFM-Optimized CAD, Thermal CFD Simulation
Sealing & Validation: IP67 / IP68 Sealing, Tolerance Stack-Up Validation
Form & Finish: Form Factor Optimization, CMF Specification, Human-Centered HMI', '', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (1, 3, '6aca16fd20848b23b44f71e5', 'chips', 'Stack we build on', '', 'iOS / Android, BLE Mesh, RS485 / Modbus, Cloud IoT Dashboards, Full-Stack Web', '', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (1, 5, '6aca16fd20848b23b44f71fa', 'logos', 'Silicon We Work With', 'Vendor families we''ve designed against, pulled out of the capability list above so procurement and CTOs can scan them at a glance.', 'Xilinx (AMD)||/api/media/file/image%20copy%208.png, Intel / Altera||/api/media/file/image%20copy%209.png, Lattice||/api/media/file/image%20copy%2010.png, Microchip||/api/media/file/image%20copy%2011.png, NXP||/api/media/file/image%20copy%2012.png, Texas Instruments||/api/media/file/image.png, Qualcomm||/api/media/file/image%20copy.png, Rockchip||/api/media/file/image%20copy%203.png, Renesas||/api/media/file/image%20copy%202.png, STMicroelectronics, Espressif||/api/media/file/image%20copy%205.png, Nordic Semiconductor||/api/media/file/image%20copy%206.png, Silicon Labs||/api/media/file/image%20copy%207.png', '', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (2, 5, '6aca16fd20848b23b44f71fb', 'rows', '', '', 'Microcontroller Families: STM32, ESP32, Nordic nRF, Silicon Labs EFR32
FPGA Families: Xilinx Artix / Zynq, Intel/Altera Cyclone / MAX, Lattice iCE40 / ECP5, Microchip PolarFire
SoC / Application Processor Families: NXP i.MX Series, TI Sitara AM Series, Qualcomm QCS Series, Rockchip RK Series, Renesas RZ/G Series', '', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (3, 5, '6aca16fd20848b23b44f71fc', 'rows', 'Protocols We''ve Worked With', 'Interfaces and buses we''ve routed and bring up in-house, not outsourced to a second vendor.', 'High-Speed Digital: DDR3/DDR4/LPDDR, PCIe Gen3/Gen4, USB 3.x / USB-C, MIPI CSI/DSI, SerDes / JESD204B, Gigabit Ethernet, Memory, HDMI
Serial Communication Protocols: I2C, I3C, SPI, RS485, CAN, USB 2.0, UART, 10/100 Ethernet', '', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (4, 5, '6aca16fd20848b23b44f71fd', 'rows', 'IPC Standards We Design To', 'The IPC standards we specify on every fab drawing and assembly note, so the board you approve is the board you can build.', 'Board Design: IPC-2221 · Generic board design, IPC-2222 · Rigid boards, IPC-7351 · SMD land patterns, IPC-2152 · Current capacity, IPC-2141 · Controlled impedance
Fabrication: IPC-6012 · Rigid board qualification, IPC-A-600 · Board acceptability
Assembly: IPC-A-610 · Assembly acceptability, J-STD-001 · Soldered assemblies', 'Class 2 as standard, Class 3 where the product demands high reliability. Design intent, not an IPC certification or a compliance claim.', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (5, 5, '6aca16fd20848b23b44f71fe', 'chips', 'Solutions We Build', '', 'BMS (Battery Management Systems), Smart Chargers, OBD-II Diagnostic Dongles, Industrial IoT Sensor Node PCBs, Medical Device PCBs, Smart Edge Gateway Boards', '', 1);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (1, 1, '6aca16fc20848b23b44f71d6', 'logos', 'Silicon We Work With', 'Vendor families we''ve written firmware for, so CTOs and procurement can scan them at a glance.', 'NXP||/api/media/file/image%20copy%2012.png, Texas Instruments||/api/media/file/image.png, Qualcomm||/api/media/file/image%20copy.png, Rockchip||/api/media/file/image%20copy%203.png, Renesas||/api/media/file/image%20copy%202.png, STMicroelectronics, Espressif||/api/media/file/image%20copy%205.png, Nordic Semiconductor||/api/media/file/image%20copy%206.png, Silicon Labs||/api/media/file/image%20copy%207.png', '', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (2, 1, '6aca16fc20848b23b44f71d7', 'rows', '', '', 'Microcontroller Families: STM32, ESP32, Nordic nRF, Silicon Labs EFR32
SoC / Application Processor Families: NXP i.MX Series, TI Sitara AM Series, Qualcomm QCS Series, Rockchip RK Series, Renesas RZ/G Series', '', 0);
INSERT INTO "capability_stacks" ("_order", "_parent_id", "id", "kind", "heading", "intro", "items", "note", "tinted") VALUES (3, 1, '6aca16fc20848b23b44f71d8', 'rows', 'Protocols We''ve Worked With', '', 'Wired Protocols: I2C, I3C, SMBus, SPI, RS485, CAN, USB 2.0, UART, 10/100 Ethernet, USB 3.0 / USB-C, USB PD, OneWire, I2S
Wireless Communication Protocols: Wi-Fi, Bluetooth, Bluetooth Mesh, LoRa, Cellular (GSM, LTE, 5G, NB-IoT), GNSS
Application Protocols: MQTT, MQTTS (MQTT over TLS), HTTPS / REST (TLS)', '', 0);
INSERT INTO "capability_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (1, 2, '6aca16fd20848b23b44f71e0', 'Do you design for sunlight and glove use?', 'Yes. Legibility and touch targets are checked on the actual target display, not a phone simulator.');
INSERT INTO "capability_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (1, 4, '6aca16fd20848b23b44f71f1', 'Is an IP67-rated gasket enough?', 'No. The whole enclosure — seams, cable entries, buttons — must be validated against real ingress conditions per IEC 60529.');
INSERT INTO "capability_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (2, 4, '6aca16fd20848b23b44f71f2', 'Can you work with our existing molder?', 'Yes. We design to their process capabilities and check DFM before a tooling quote.');
INSERT INTO "capability_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (1, 3, '6aca16fd20848b23b44f71e6', 'Single device or a fleet?', 'Both. Auth, pairing and telemetry costs are designed for fleet scale from the start.');
INSERT INTO "capability_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (1, 5, '6aca16fd20848b23b44f71ff', 'Do you also write the firmware for the boards you design?', 'Yes. The same team does both, so hardware and firmware are validated against each other during bring-up.');
INSERT INTO "capability_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (2, 5, '6aca16fd20848b23b44f7200', 'Can you take over a board another vendor started?', 'Yes. We review the existing schematic and layout first and flag risks before changing anything.');
INSERT INTO "capability_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (1, 1, '6aca16fc20848b23b44f71d9', 'FreeRTOS or Zephyr — which should we use?', 'It depends on the MCU, connectivity stack and certification path. We recommend one at the scoping call, with the reasoning written down.');
INSERT INTO "capability_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (2, 1, '6aca16fc20848b23b44f71da', 'Can you add OTA to a product already in the field?', 'Often, if the flash layout allows a second image. We assess this before quoting.');
