INSERT INTO "industry" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "summary", "challenges_heading", "challenges", "disciplines_heading", "disciplines", "callout_heading", "callout_text", "products_heading", "products", "projects_heading", "process_heading", "process_highlight", "process_cta_label", "process_cta_href", "process", "faq_heading", "others_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at") VALUES (3, 'Consumer Tech', 'consumer-tech', 'Consumer Tech electronics', 'Consumer Tech Electronics Product Development in India', 'Compact, battery-powered and connected devices, from schematic to enclosure and app.', 'Talk to an Engineer', '#consultation', 'See Consumer Tech projects', '#projects', NULL, 'A compact handheld consumer device beside its open PCB', 'Compact, battery-powered and connected devices, from schematic to enclosure and app.', '', '', '', '', '', '', '', '', 'Consumer Tech Projects', '', '', '', '', '', '', 'Other Industries We Build For', 'Consumer Electronics Development, India | Canopy Embedded Labs', 'Compact, battery-powered and connected devices, from schematic to enclosure and app.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-10T10:44:14.236Z', '2026-10-10T10:35:55.407Z');
INSERT INTO "industry" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "summary", "challenges_heading", "challenges", "disciplines_heading", "disciplines", "callout_heading", "callout_text", "products_heading", "products", "projects_heading", "process_heading", "process_highlight", "process_cta_label", "process_cta_href", "process", "faq_heading", "others_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at") VALUES (4, 'EV', 'ev', 'EV electronics · Battery · Charging · Telematics', 'EV Electronics Product Development in India — Battery to Cloud.', 'Battery management, charging and telematics electronics for EV makers and suppliers: PCB, firmware, enclosure and cloud from one team, with zero vendor handoffs.', 'Talk to an Engineer', '#consultation', 'See EV projects', '#projects', NULL, 'A battery management PCB inside an EV battery pack, close-up', 'Battery management, charging and telematics electronics for EV makers and suppliers.', 'Where EV Electronics Programmes Slip', 'Battery safety is a system problem | Cell monitoring, protection circuitry and firmware limits have to agree. When the board and the firmware come from different vendors, the gaps show up late, in validation.
Field updates decide service cost | A vehicle in the field needs firmware that can be updated. An OTA-ready architecture with a dual-bank bootloader turns a defect into a patch, not a recall.
Heat and ingress decide durability | Thermal validation and IP67-class sealing belong in the enclosure design from the start, not after the first test failure.', 'What We Build for EV, Schematic to Cloud', 'PCB Design & Layout | BMS and charger boards: multi-cell monitoring, high-current power stages, noise and isolation handled in layout. | /capabilities/pcb-design/
Firmware Engineering | State-of-charge and health tracking, protection logic, interfaces such as CAN and UART, and a dual-bank bootloader that is ready for signed OTA with automatic rollback. | /capabilities/firmware/
Mechanical & Industrial Design | Pack and charger enclosures with thermal CFD, IP67/IP68 sealing and tolerance stack-up checked before tooling. | /capabilities/mechanical-industrial-design/
Embedded HMI & UI/UX | Displays and companion apps that show state of charge, faults and service data clearly. | /capabilities/hmi-ui-ux/
IoT Apps & Cloud | Telematics dashboards and BLE/Wi-Fi apps for fleet monitoring, alerts and battery health history. | /capabilities/iot-apps-cloud/', 'One team. One contract.', 'All five disciplines for your EV product, run in parallel.', 'Typical EV Products We Engineer', 'Battery management systems | Cell monitoring, balancing and protection for 2W, 3W and light-vehicle packs.
Chargers and charging electronics | Portable and on-board chargers with power stages and control firmware engineered together.
Telematics and tracking units | Connected units reporting location, battery state and faults to a cloud dashboard.
Displays and rider interfaces | Instrument clusters and companion apps designed against the real display and firmware.', 'EV Projects We Have Delivered', 'How We Run an EV Programme: Ideate. Innovate.', 'Deploy.', 'See the full six-step engagement model', '/engagement-model/', 'Ideate | Scope the product and review safety, thermal and update-path risks before any layout starts.
Innovate | Hardware, firmware and enclosure move in parallel, so integration problems surface early.
Deploy | Validation, production handover and a firmware update path for the field.', 'EV Electronics FAQ', 'Other Industries We Build For', 'EV Electronics Development, India | Canopy Embedded Labs', 'Battery management, charging and telematics electronics for EV makers in India: PCB, firmware, enclosure and cloud from one team.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-10T10:44:14.380Z', '2026-10-10T10:35:55.482Z');
INSERT INTO "industry" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "summary", "challenges_heading", "challenges", "disciplines_heading", "disciplines", "callout_heading", "callout_text", "products_heading", "products", "projects_heading", "process_heading", "process_highlight", "process_cta_label", "process_cta_href", "process", "faq_heading", "others_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at") VALUES (5, 'Industrial IoT', 'industrial-iot', 'Industrial IoT electronics', 'Industrial IoT Electronics Product Development in India', 'Gateways, sensor nodes and RS485/Modbus monitoring built for 24/7 uptime.', 'Talk to an Engineer', '#consultation', 'See Industrial IoT projects', '#projects', NULL, 'An industrial gateway mounted on a DIN rail beside a control cabinet', 'Gateways, sensor nodes and RS485/Modbus monitoring built for 24/7 uptime.', '', '', '', '', '', '', '', '', 'Industrial IoT Projects', '', '', '', '', '', '', 'Other Industries We Build For', 'Industrial IoT Device Development, India | Canopy Embedded Labs', 'Gateways, sensor nodes and RS485/Modbus monitoring built for 24/7 uptime.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-10T10:44:14.546Z', '2026-10-10T10:35:55.622Z');
