INSERT INTO "industry_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (1, 4, '6aca16fe20848b23b44f7203', 'Do you build the whole battery management system, or only the firmware?', 'Both, plus the PCB, the enclosure and the cloud dashboard. One team and one contract, so there is no handoff between board and firmware vendors.');
INSERT INTO "industry_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (2, 4, '6aca16fe20848b23b44f7204', 'Can the battery firmware be updated after the vehicle is sold?', 'Our BMS architecture is OTA-ready: a dual-bank bootloader with automatic rollback, so updates can be delivered when your platform supports them.');
INSERT INTO "industry_faqs" ("_order", "_parent_id", "id", "question", "answer") VALUES (3, 4, '6aca16fe20848b23b44f7205', 'Can you start from our existing cell and pack design?', 'Yes. We can take on the electronics around your chosen cells and pack layout, or take the product from concept.');
